    <L::Service as Service<Request<NewReqBody>>>::Future: Send + 'static,
    NewReqBody: HttpBody + 'static,
{
    let routes = self
        .routes
        .into_iter()
        .map(|(id, endpoint)| {
            let route = endpoint.layer(layer.clone());
            (id, route)
        })
        .collect();

    let fallback = self.fallback.map(|route| route.layer(layer));

    Router {
        routes,
        node: self.node,
        fallback,
    }
}

